//! Ogg page CRC-32, matching FFmpeg's `ff_crc04C11DB7_update` /
//! `av_crc(AV_CRC_32_IEEE, ...)`.
//!
//! FFmpeg seeds the checksum with `av_crc(AV_CRC_32_IEEE, 0, "OggS", 4)` and
//! then feeds the rest of the header, four zero bytes in place of the stored
//! CRC, the segment table and the page body.  Feeding the whole page with the
//! CRC field zeroed, starting from 0, is equivalent because the "OggS" prefix
//! is part of the page.
//!
//! The `AV_CRC_32_IEEE` table generated by `av_crc_init(..., le = 0, ...)` is
//! the byte-swapped version of the classic 0x04C11DB7 MSB-first table.

/// Build the 256-entry CRC table used by `av_crc(AV_CRC_32_IEEE, ...)`.
const fn build_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut c = (i as u32) << 24;
        let mut j = 0usize;
        while j < 8 {
            c = if c & 0x8000_0000 != 0 {
                (c << 1) ^ 0x04c1_1db7
            } else {
                c << 1
            };
            j += 1;
        }
        // av_bswap32(c)
        table[i] = c.swap_bytes();
        i += 1;
    }
    table
}

static CRC_TABLE: [u32; 256] = build_crc_table();

/// Update a running Ogg CRC with `data`.
pub fn crc_update(crc: u32, data: &[u8]) -> u32 {
    let mut crc = crc;
    for &byte in data {
        crc = CRC_TABLE[((crc ^ byte as u32) & 0xff) as usize] ^ (crc >> 8);
    }
    crc
}

/// Compute the Ogg CRC of a complete page whose CRC field (bytes 22..26) is
/// zeroed.
pub fn page_crc(page: &[u8]) -> u32 {
    crc_update(0, page)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_ogg_crc_values() {
        // CRC of "OggS" with FFmpeg's algorithm, from the comment in
        // libavformat/ogg/demuxer.c.
        assert_eq!(crc_update(0, b"OggS"), 0x4fa9_b05f);

        // First page of fate-suite/vorbis/1.0.1-test_small.ogg, with its CRC
        // field zeroed. The stored CRC is 0xb8541d0a.
        let mut first_page: Vec<u8> = vec![
            0x4f, 0x67, 0x67, 0x53, 0x00, 0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x32, 0xd4, 0x0a, 0x48, 0x00, 0x00, 0x00, 0x00, 0xb8, 0x54, 0x1d, 0x0a, 0x01, 0x1e,
            0x01, 0x76, 0x6f, 0x72, 0x62, 0x69, 0x73, 0x00, 0x00, 0x00, 0x00, 0x02, 0x44, 0xac,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x81, 0xb5, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00,
            0xb8, 0x01,
        ];
        first_page[22..26].copy_from_slice(&[0, 0, 0, 0]);
        assert_eq!(page_crc(&first_page), 0xb854_1d0a);
    }
}
